import{_ as n,c as i,o as a,a3 as t}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Einführung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1786595765000}'),r={name:"de/guide/introduction.md"};function l(s,e,o,u,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="einfuhrung" tabindex="-1">Einführung <a class="header-anchor" href="#einfuhrung" aria-label="Permalink to &quot;Einführung&quot;">​</a></h1><h2 id="uber-clipboardxai" tabindex="-1">Über ClipboardxAI <a class="header-anchor" href="#uber-clipboardxai" aria-label="Permalink to &quot;Über ClipboardxAI&quot;">​</a></h2><p><strong>ClipboardxAI</strong> ist ein intelligenter Zwischenablagen-Manager für macOS. Jedes Mal, wenn Sie Text, Code oder einen Link kopieren, wird dieser in einem durchsuchbaren Verlauf in der Menüleiste gespeichert. Mit einem Klick — oder vollautomatisch — können Sie eine Aktion auf diesen Eintrag anwenden: ihn zusammenfassen, übersetzen, aufräumen oder an ein Cloud-KI-Modell übergeben.</p><p>Es basiert auf zwei Arten von Werkzeugen:</p><ul><li><strong>Eingebaute lokale Werkzeuge</strong>, die vollständig auf Ihrem Mac ausgeführt werden, ohne Netzwerkverbindung.</li><li><strong>KI-Aktionen</strong>, die ein Cloud-Modell aufrufen, das Sie selbst konfigurieren (Ihr eigener API-Schlüssel, gespeichert im systemeigenen Keychain).</li></ul><h2 id="hauptfunktionen" tabindex="-1">Hauptfunktionen <a class="header-anchor" href="#hauptfunktionen" aria-label="Permalink to &quot;Hauptfunktionen&quot;">​</a></h2><h3 id="📋-zwischenablagen-verlauf" tabindex="-1">📋 Zwischenablagen-Verlauf <a class="header-anchor" href="#📋-zwischenablagen-verlauf" aria-label="Permalink to &quot;📋 Zwischenablagen-Verlauf&quot;">​</a></h3><p>Alles, was Sie kopieren, wird automatisch erfasst und in einem durchsuchbaren Verlauf aufbewahrt. Springen Sie über die Menüleiste zu jedem früheren Eintrag zurück — keine verlorenen Schnipsel mehr.</p><h3 id="⚡-intelligente-vorschlage" tabindex="-1">⚡ Intelligente Vorschläge <a class="header-anchor" href="#⚡-intelligente-vorschlage" aria-label="Permalink to &quot;⚡ Intelligente Vorschläge&quot;">​</a></h3><p>ClipboardxAI schlägt die passendsten Aktionen für den aktuellen Eintrag vor. Nehmen Sie einen Vorschlag an oder durchsuchen Sie die vollständige Liste der Werkzeuge.</p><h3 id="🛠️-eingebaute-lokale-werkzeuge" tabindex="-1">🛠️ Eingebaute lokale Werkzeuge <a class="header-anchor" href="#🛠️-eingebaute-lokale-werkzeuge" aria-label="Permalink to &quot;🛠️ Eingebaute lokale Werkzeuge&quot;">​</a></h3><p>Offline, privat, sofort:</p><ul><li><strong>Extract Links</strong> — extrahiert jede URL aus einem Textblock.</li><li><strong>Count Stats</strong> — Wort-, Zeichen-, Zeilen- und Satzzählung.</li><li><strong>Collapse Blank Lines</strong> — bereinigt eingefügten Text in einem Schritt.</li></ul><p>Mit der Zeit können weitere lokale Werkzeuge hinzukommen — sie verlassen niemals Ihr Gerät.</p><h3 id="✨-ki-aktionen" tabindex="-1">✨ KI-Aktionen <a class="header-anchor" href="#✨-ki-aktionen" aria-label="Permalink to &quot;✨ KI-Aktionen&quot;">​</a></h3><p>Senden Sie den aktuellen Eintrag an ein Cloud-Modell, um:</p><ul><li><strong>Summarize</strong> — lange Artikel und Threads zusammenzufassen.</li><li><strong>Translate</strong> — zwischen Sprachen zu übersetzen.</li><li><strong>Rewrite / polish</strong> — Ton und Klarheit zu verbessern.</li><li>eine beliebige Aktion aus dem <strong>Marketplace</strong> auszuführen.</li></ul><h3 id="🛒-aktions-marktplatz" tabindex="-1">🛒 Aktions-Marktplatz <a class="header-anchor" href="#🛒-aktions-marktplatz" aria-label="Permalink to &quot;🛒 Aktions-Marktplatz&quot;">​</a></h3><p>Durchsuchen Sie von der Community erstellte KI-Aktionen und installieren Sie diese mit einem Klick über einen Deep-Link (<code>clipboardxai://install?action=&lt;id&gt;</code>). Kategorien umfassen Writing, Developer, Productivity, Translate, Social und Analytics.</p><h3 id="🔒-privat-konzipiert" tabindex="-1">🔒 Privat konzipiert <a class="header-anchor" href="#🔒-privat-konzipiert" aria-label="Permalink to &quot;🔒 Privat konzipiert&quot;">​</a></h3><p>Ihr Zwischenablagen-Verlauf bleibt auf Ihrem Gerät. Cloud-KI ist <strong>opt-in</strong>: Wenn aktiviert, werden Inhalte nur an den von <em>Ihnen</em> gewählten Anbieter gesendet, unter Verwendung eines im Keychain gespeicherten API-Schlüssels. Wir empfangen oder speichern Ihre Einträge niemals, und es gibt keine Analyse oder Telemetrie.</p><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to &quot;Systemanforderungen&quot;">​</a></h2><ul><li><strong>Betriebssystem</strong>: macOS 14 Sonoma oder neuer</li><li><strong>Prozessor</strong>: Apple Silicon (M-Serie) oder Intel (64-Bit)</li><li><strong>Arbeitsspeicher</strong>: mindestens 4 GB RAM, empfohlen 8 GB</li><li><strong>Speicher</strong>: ca. 50 MB für die Installation</li><li><strong>Für Cloud-KI</strong>: ein API-Schlüssel eines unterstützten Anbieters (DeepSeek, MiniMax, Zhipu GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic oder Gemini)</li></ul><h2 id="unterstutzte-sprachen" tabindex="-1">Unterstützte Sprachen <a class="header-anchor" href="#unterstutzte-sprachen" aria-label="Permalink to &quot;Unterstützte Sprachen&quot;">​</a></h2><p>Die App und diese Website unterstützen Englisch, Vereinfachtes Chinesisch (简体中文), Traditionelles Chinesisch (繁體中文), Japanisch (日本語), Deutsch, Spanisch und Französisch.</p><h2 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to &quot;Erste Schritte&quot;">​</a></h2><p>Wenn Sie neu bei ClipboardxAI sind, beginnen Sie mit der <a href="/de/guide/installation.html">Installationsanleitung</a>, um die App auf Ihrem Mac zum Laufen zu bringen, und lesen Sie dann <a href="/de/guide/usage.html">Nutzung</a>, um zu erfahren, wie Aktionen funktionieren.</p>',27)])])}const p=n(r,[["render",l]]);export{g as __pageData,p as default};
